// Real signed token validation, not a map-only decoder test. No service needed.
package main
import("encoding/json";"os";"time";"github.com/golang-jwt/jwt/v5";"github.com/livekit/protocol/auth")
type input struct{ID string `json:"id"`;Claims json.RawMessage `json:"claims"`}
func main(){f,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};var cases []input;if e=json.NewDecoder(f).Decode(&cases);e!=nil{panic(e)};if e=f.Close();e!=nil{panic(e)};if len(cases)!=8{panic("all8")};seen:=map[string]bool{};for _,c:=range cases{if c.ID==""||seen[c.ID]{panic("unique8")};seen[c.ID]=true;var claims jwt.MapClaims;if e=json.Unmarshal(c.Claims,&claims);e!=nil{panic(e)};claims["iss"]="owned-key";claims["sub"]="owned-identity";claims["exp"]=time.Now().Add(time.Hour).Unix();claims["video"]=map[string]any{"roomJoin":true,"room":"owned"};token,e:=jwt.NewWithClaims(jwt.SigningMethodHS256,claims).SignedString([]byte("owned-secret"));if e!=nil{panic(e)};v,e:=auth.ParseAPIToken(token);if e!=nil{panic(e)};_,grants,err:=v.Verify("owned-secret");out:=map[string]any{"id":c.ID,"accepted":err==nil,"scope":"actual original signed JWT ParseAPIToken + Verify"};if err!=nil{out["error"]=err.Error()}else{out["kind_details"]=grants.KindDetails};if e=json.NewEncoder(os.Stdout).Encode(out);e!=nil{panic(e)}}}
